	public void addThrows(MethodNode mth, ICodeWriter code) {
		List<ArgType> throwList = mth.getThrows();
		if (!throwList.isEmpty()) {
			code.add(" throws ");
			for (Iterator<ArgType> it = throwList.iterator(); it.hasNext();) {
				ArgType ex = it.next();
				classGen.useType(code, ex);
				if (it.hasNext()) {
					code.add(", ");
				}
			}
		}
